def generate_coeff(id_coeffs, exp_coeffs, tex_coeffs, angles, gammas, translations):
    id_coeffs_tensor = torch.from_numpy(np.array(id_coeffs))
    exp_coeffs_tensor = torch.from_numpy(np.array(exp_coeffs))
    tex_coeffs_tensor = torch.from_numpy(np.array(tex_coeffs))
    angles_tensor = torch.from_numpy(np.array(angles))
    gammas_tensor = torch.from_numpy(np.array(gammas))
    translations_tensor = torch.from_numpy(np.array(translations))
    coeffs_tensor = torch.cat((id_coeffs_tensor, exp_coeffs_tensor, tex_coeffs_tensor,
                               angles_tensor, gammas_tensor, translations_tensor), dim=0)
    coeffs_tensor = coeffs_tensor.reshape(1, -1)
    return coeffs_tensor.to(device)  


