def render_image(save_folder, name, vector):
    # Create output directory
    if not os.path.exists(save_folder):
        os.makedirs(save_folder)

    id_coeffs = vector[:80]
    tex_coeffs = vector[80:]
    exp_coeffs = [0] * 64
    # gammas = [0] * 27
    gammas = [
        -0.19591527, 0.041457467, 0.025054021, 0.13086502, -0.019033769, -0.063858435,
        0.12968077, 0.17377149, 0.036793500, -0.19474666, 0.037832744, 0.036348913,
        0.14034632, -0.032831065, -0.061886676, 0.14463221, 0.22639619, 0.054289468,
        -0.19493547, 0.030089460, 0.041697804, 0.15286742, -0.054598290, -0.079185203,
        0.16155738, 0.25850582, 0.062397130
    ]

    translations = [0] * 3

    # View angles: front and side
    view_angles = {
        "front": [0, 0, 0],
        "half": [0, -np.pi / 4, 0],  # yaw = +45° in radians,
        "side": [0, -np.pi / 2, 0]  # yaw = +45° in radians
    }

    for view_name, angles in view_angles.items():
        input_coeff = generate_coeff(id_coeffs, exp_coeffs, tex_coeffs, angles, gammas, translations)
        pred_vertex, pred_tex, pred_color, pred_lm, pred_lm3dland = facemodel.compute_for_render(input_coeff)
        pred_mask, _, pred_face = renderer(mesh_rasterizer, pred_vertex.float(), facemodel.face_buf.float(), feat=pred_color.float())

        # Black background
        input_img = torch.zeros((1, 3, 224, 224), dtype=torch.float32).to(device)
        _, output_img_black_bg, _ = compute_visuals_rec_only(pred_face, pred_mask, input_img)
        image_numpy_black_bg = tensor2im(output_img_black_bg)

        # Save image
        img_path_black_bg = os.path.join(save_folder, f"{name}_{view_name}.png")
        save_image(image_numpy_black_bg, img_path_black_bg)
        print(f"Saved to: {img_path_black_bg}")

